package com.naang360.redmi3dscanner;
import android.content.*;import android.hardware.*;
public final class SensorFusion implements SensorEventListener {private final SensorManager m;private final float[] R=new float[9],o=new float[3],g=new float[3],mag=new float[3];public SensorFusion(Context c){m=(SensorManager)c.getSystemService(Context.SENSOR_SERVICE);Sensor a=m.getDefaultSensor(Sensor.TYPE_ACCELEROMETER),x=m.getDefaultSensor(Sensor.TYPE_MAGNETIC_FIELD);if(a!=null)m.registerListener(this,a,SensorManager.SENSOR_DELAY_GAME);if(x!=null)m.registerListener(this,x,SensorManager.SENSOR_DELAY_GAME);}public boolean hasGyroscope(){return m.getDefaultSensor(Sensor.TYPE_GYROSCOPE)!=null;}public boolean hasMagnetometer(){return m.getDefaultSensor(Sensor.TYPE_MAGNETIC_FIELD)!=null;}public boolean hasAccelerometer(){return m.getDefaultSensor(Sensor.TYPE_ACCELEROMETER)!=null;}public void onSensorChanged(SensorEvent e){if(e.sensor.getType()==Sensor.TYPE_ACCELEROMETER)System.arraycopy(e.values,0,g,0,3);else if(e.sensor.getType()==Sensor.TYPE_MAGNETIC_FIELD)System.arraycopy(e.values,0,mag,0,3);SensorManager.getRotationMatrix(R,null,g,mag);SensorManager.getOrientation(R,o);}public void onAccuracyChanged(Sensor s,int a){}public void close(){m.unregisterListener(this);}}